<script setup>
import {ref,reactive,onActivated} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {http} from '../api/http'
import {auth} from '../stores/auth'
import {useDirty} from '../stores/dirty'
const personal=auth.user?.role==='EMPLOYEE',base=personal?'/employee/leaves':'/leaves'
const rows=ref([]),total=ref(0),busy=ref(false),dialog=ref(false),saving=ref(false)
const filter=reactive({keyword:'',status:null,page:1,page_size:10}),form=reactive({leave_type:'personal',start_date:'',end_date:'',reason:''})
const types={personal:'事假',sick:'病假',annual:'年假'},statuses={pending:'待审批',approved:'已通过',rejected:'已驳回',cancelled:'已撤销'}
const resetDirty=useDirty(()=>form,()=>dialog.value)
async function load(){busy.value=true;try{const r=await http.get(base,{params:filter});rows.value=r.data;total.value=r.total}catch{}finally{busy.value=false}}
async function submit(){saving.value=true;try{await http.post(base,form);dialog.value=false;resetDirty();ElMessage.success('申请已提交');load()}catch{}finally{saving.value=false}}
async function action(row,kind){let body={};if(kind==='reject'){try{const r=await ElMessageBox.prompt('请输入驳回原因','驳回请假',{inputValidator:v=>!!v?.trim()||'请填写原因'});body={rejection_reason:r.value}}catch{return}}else{try{await ElMessageBox.confirm(kind==='approve'?'确认通过？对应工作日将生成请假考勤，存在冲突时会回滚。':'确认撤销此待审批申请？','操作确认',{type:'warning'})}catch{return}}try{await http.post(`${base}/${row.id}/${kind}`,body);ElMessage.success('操作成功');load()}catch{}}
onActivated(load)
</script>
<template><div class="page-title"><div><h1>{{personal?'请假申请':'请假审批'}}</h1><p>整天请假按周一至周五联动考勤，周末不生成记录。</p></div><el-button v-if="personal" type="primary" @click="Object.assign(form,{leave_type:'personal',start_date:'',end_date:'',reason:''});dialog=true">申请请假</el-button></div><el-card shadow="never"><el-form inline class="filters"><el-form-item v-if="!personal" label="姓名"><el-input v-model="filter.keyword"/></el-form-item><el-form-item label="状态"><el-select v-model="filter.status" clearable><el-option v-for="(label,value) in statuses" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-button @click="filter.page=1;load()">查询</el-button><el-button @click="Object.assign(filter,{keyword:'',status:null,page:1});load()">重置</el-button></el-form><el-table v-loading="busy" :data="rows" empty-text="暂无申请"><el-table-column prop="name" label="姓名"/><el-table-column label="类型"><template #default="{row}">{{types[row.leave_type]}}</template></el-table-column><el-table-column prop="start_date" label="开始日期"/><el-table-column prop="end_date" label="结束日期"/><el-table-column prop="reason" label="请假原因" min-width="160"/><el-table-column label="状态"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column prop="rejection_reason" label="驳回原因"/><el-table-column label="操作" width="160"><template #default="{row}"><template v-if="row.status==='pending'"><el-button v-if="personal" link type="warning" @click="action(row,'cancel')">撤销</el-button><template v-else><el-button link type="success" @click="action(row,'approve')">通过</el-button><el-button link type="danger" @click="action(row,'reject')">驳回</el-button></template></template></template></el-table-column></el-table><el-pagination class="pagination" v-model:current-page="filter.page" :page-size="10" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><WorkspaceDialog v-model="dialog" title="申请请假" width="540px"><el-form label-position="top"><el-form-item label="请假类型" required><el-select v-model="form.leave_type"><el-option v-for="(label,value) in types" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="开始日期" required><el-date-picker v-model="form.start_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期" required><el-date-picker v-model="form.end_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="请假原因" required><el-input v-model="form.reason" type="textarea" maxlength="1000"/></el-form-item><el-button type="primary" :loading="saving" @click="submit">提交申请</el-button></el-form></WorkspaceDialog></template>
